import subprocess, itertools
ESC = set('.*+?^$()[]{}|')
def run(b, args=None):
    if isinstance(b,str): b=b.encode()
    p = subprocess.run(['/workspace/executable']+(args or [])+['-'], input=b, capture_output=True)
    return p.returncode, p.stdout.decode('utf8','replace'), p.stderr

def esc_literal(content):
    out = ''.join(('\\'+c) if c in ESC else c for c in content)
    return out

def unquote(s, q):
    return s.replace('\\'+q, q)

def model_literal(content, q):
    return unquote(esc_literal(content), q)

def is_unit(s):
    n = len(s)
    if n == 1: return True
    if n == 2: return s[0] == '\\'
    if n == 0: return False
    return (s[0]=='(' and s[-1]==')') or (s[0]=='[' and s[-1]==']')

def model(content, q, quant=None):
    body = model_literal(content, q)
    if quant is None: return body
    if not is_unit(body): body = '(?:'+body+')'
    return body + quant

# Test: single-char and multi-char, all ASCII printable except quote/backslash, plus escapes
fails = 0; total = 0
chars = [chr(i) for i in range(0x20,0x7f) if chr(i) not in '"\\'] + ['é','🎉','日','\t','\n','\r']
escapes = ['\\"','\\\\','\\/','\\b','\\f','\\n','\\r','\\t','\\u0041','\\uFFFF']
bodies = chars + escapes + ['a'+c for c in chars[:20]] + [e+'x' for e in escapes] + ['','ab','abc','..','\\\\a','\\\\\\\\']
for body in bodies:
    for q in ['"']:
        for quant, src in [(None,'%s%s%s;'), ('{2}','2 of %s%s%s;'), ('+','some of %s%s%s;'), ('*','any of %s%s%s;'), ('?','option of %s%s%s;'), ('{2,5}','2 to 5 of %s%s%s;'), ('{4,}','over 3 of %s%s%s;')]:
            s = src % (q, body, q)
            rc,o,e = run(s)
            total += 1
            if rc != 0:
                print("UNEXPECTED ERROR for %r: %s" % (s, e.decode()[:80])); fails+=1; continue
            exp = model(body, q, quant) + '\n'
            if o != exp:
                print("MISMATCH src=%r got=%r exp=%r" % (s,o,exp)); fails+=1
print("total=%d fails=%d" % (total,fails))
